#!/usr/bin/env python3
# apply_fleet_marks.py — fence FLEET_MARKS_20260928
# (requires FLEET_CHART_V2_20260928 in fleet_today_routes.py + its test,
#  FLEET_KPIS_PERIOD_20260928 in FleetKpis.jsx)
#
# Why MTM / Unrealised fell off a cliff after 15:40 (28 Sep): LTPStore is an
# in-memory dict fed only by WebSocket ticks. After the close no ticks arrive,
# and the rebuild's backend restart emptied it; an open leg whose engine does
# not REST-refresh its own mark then had NO price and counted 0 — hence the ≈
# and an unrealised that dropped from 2.18L to 72k while the chart's last
# sample (15:40, full marks) still said +1.47L.
# Fix: every mark this feed sees is remembered in-process and persisted to a
# new fleet_last_marks(symbol, ltp, ts) table (throttled to one write per
# 30 s); a leg with no live tick is valued at its last seen mark and the row /
# book says so ("marks as of 15:40" under the MTM). Only a symbol never seen
# at all still counts 0 and flags ≈. Post-close, after restarts and
# pre-market next morning the numbers now hold at the last real marks.
#
#   backend  fleet_today_routes.py (anchored), test_fleet_today_routes.py (whole; 81 checks)
#            v2 (28 Sep, evening): mark timestamps are compared with a tolerance —
#            the first cut assumed the suite ran inside one second of its start
#            (passed here, failed on the Mac); a minute roll between two polls is
#            also tolerated in the self-sample check.
#   frontend components/fleet/FleetKpis.jsx (one anchored edit: the stale-marks note)
#
# Deploy: ./desktop/build-scalp.sh both — after 15:40 IST.
#
# Run ONLY this script:
#   cd /Users/anbu/dev/scalp-app && python3 apply_fleet_marks.py [--allow-dirty] [--skip-tests]
from __future__ import annotations
import base64, os, py_compile, shutil, subprocess, sys, tempfile

FENCE = "FLEET_MARKS_20260928"
ROOT = os.path.dirname(os.path.abspath(__file__))
ROUTE = "backend/app/api/fleet_today_routes.py"
TEST = "backend/app/api/test_fleet_today_routes.py"
KPIS = "frontend/src/components/fleet/FleetKpis.jsx"
MIRRORS = (("backend/app", "desktop/src-tauri/backend/app"), ("frontend/src", "desktop/src-tauri/frontend/src"))
PREREQ = {ROUTE: "FLEET_CHART_V2_20260928", TEST: "FLEET_CHART_V2_20260928", KPIS: "FLEET_KPIS_PERIOD_20260928"}
EDITS = {'backend/app/api/fleet_today_routes.py': [('replace', 'def _stop_for(sid: str, book: str) -> Optional[float]:\n', '# ── FLEET_MARKS_20260928 ── last-seen marks. LTPStore is memory-only and\n# tick-fed: after 15:40 no ticks arrive, and a backend restart empties it, so\n# an open leg whose engine does not REST-refresh its mark had NO price and\n# counted 0 (the ≈ MTM that drops after close). Every mark this module sees\n# is remembered in-process and persisted to fleet_last_marks(symbol, ltp, ts)\n# (throttled); a leg with no live mark is valued at its last seen one and the\n# row says so (marks_stale / mark_asof). Only a symbol never seen at all\n# still counts 0 and flags approx.\nMARKS_WRITE_EVERY_S = 30\n_seen_marks: Dict[str, tuple] = {}      # symbol -> (ltp, ts) seen live in this process\n_marks_dirty: Dict[str, tuple] = {}\n_marks_last_write = [0.0]\n_db_marks: Dict[str, tuple] = {}        # fleet_last_marks, loaded once per compute\n\n\ndef _ensure_marks_table(conn) -> None:\n    conn.execute("CREATE TABLE IF NOT EXISTS fleet_last_marks ("\n                 " symbol TEXT PRIMARY KEY, ltp REAL NOT NULL, ts INTEGER NOT NULL)")\n\n\ndef _load_db_marks() -> None:\n    try:\n        with sqlite3.connect(_db_path(), timeout=30) as conn:\n            _ensure_marks_table(conn)\n            _db_marks.clear()\n            for sym, ltp, ts in conn.execute("SELECT symbol, ltp, ts FROM fleet_last_marks"):\n                _db_marks[sym] = (float(ltp), int(ts))\n    except Exception:\n        pass\n\n\ndef _persist_marks(now: int, force: bool = False) -> int:\n    if not _marks_dirty or (not force and now - _marks_last_write[0] < MARKS_WRITE_EVERY_S):\n        return 0\n    batch = dict(_marks_dirty)\n    try:\n        with sqlite3.connect(_db_path(), timeout=30) as conn:\n            _ensure_marks_table(conn)\n            conn.executemany("INSERT OR REPLACE INTO fleet_last_marks (symbol, ltp, ts) VALUES (?,?,?)",\n                             [(s, float(v[0]), int(v[1])) for s, v in batch.items()])\n            conn.commit()\n    except Exception:\n        return 0\n    for s in batch:\n        _marks_dirty.pop(s, None)\n    _marks_last_write[0] = now\n    return len(batch)\n\n\ndef _mark(symbol: str, now: int):\n    """(ltp, mark_ts, stale) — live mark first, else the last seen one."""\n    ltp = _ltp(symbol)\n    if ltp is not None:\n        _seen_marks[symbol] = (ltp, now)\n        _marks_dirty[symbol] = (ltp, now)\n        return ltp, now, False\n    m = _seen_marks.get(symbol) or _db_marks.get(symbol)\n    if m:\n        return float(m[0]), int(m[1]), True\n    return None, None, False\n\n\ndef _stop_for(sid: str, book: str) -> Optional[float]:\n'), ('replace', '    unreal = 0.0\n    missing = 0\n    for l in open_:\n        ltp = _ltp(l["symbol"])\n        if ltp is None or l["entry"] is None:\n            missing += 1\n            continue\n', '    unreal = 0.0\n    missing = 0\n    stale = 0\n    mark_asof = None\n    for l in open_:\n        ltp, mts, is_stale = _mark(l["symbol"], now)   # ── FLEET_MARKS_20260928 ──\n        if ltp is None or l["entry"] is None:\n            missing += 1\n            continue\n        if is_stale:\n            stale += 1\n            mark_asof = mts if mark_asof is None else min(mark_asof, mts)\n'), ('replace', '        "ltp_missing": missing, "approx": approx,\n        "stop": _stop_for(sid, book) if open_ else None,\n', '        "ltp_missing": missing, "approx": approx,\n        "marks_stale": stale, "mark_asof": mark_asof,   # ── FLEET_MARKS_20260928 ──\n        "stop": _stop_for(sid, book) if open_ else None,\n'), ('replace', 'def _compute(now: int, warns: list) -> List[dict]:\n    day0 = _cr._day_start(now)\n    rows: List[dict] = []\n', 'def _compute(now: int, warns: list) -> List[dict]:\n    day0 = _cr._day_start(now)\n    rows: List[dict] = []\n    _load_db_marks()   # ── FLEET_MARKS_20260928 ──\n'), ('replace', '                             "first_entry_ts": None, "last_event": None, "error": True,\n', '                             "first_entry_ts": None, "last_event": None, "error": True,\n                             "marks_stale": 0, "mark_asof": None,\n'), ('replace', '                             "month": {"net": 0.0, "trades": 0, "approx": True}})\n    return rows\n', '                             "month": {"net": 0.0, "trades": 0, "approx": True}})\n    _persist_marks(now)   # ── FLEET_MARKS_20260928 ── throttled\n    return rows\n'), ('replace', '            "rows": len(mine),\n            "approx": any(r["approx"] for r in mine),\n', '            "rows": len(mine),\n            "approx": any(r["approx"] for r in mine),\n            # ── FLEET_MARKS_20260928 ── legs valued at their last seen mark, oldest such mark\n            "marks_stale": sum(r.get("marks_stale", 0) for r in mine),\n            "mark_asof": min((r["mark_asof"] for r in mine if r.get("mark_asof")), default=None),\n')], 'frontend/src/components/fleet/FleetKpis.jsx': [('replace', '        {!idle && t.approx ? "≈" : ""}{fmtInr(idle ? 0 : t.gross)}\n      </span>\n', '        {!idle && t.approx ? "≈" : ""}{fmtInr(idle ? 0 : t.gross)}\n        {!idle && t.marks_stale > 0 && t.mark_asof && (   /* ── FLEET_MARKS_20260928 ── */\n          <span title={`${t.marks_stale} open leg${t.marks_stale > 1 ? "s" : ""} valued at the last mark seen (no live tick)`}\n            style={{ display: "block", fontSize: 10.5, fontWeight: 400, letterSpacing: 0, color: colors.text.muted, marginTop: 1 }}>\n            marks as of {hhmm(Math.floor(((t.mark_asof + 19800) % 86400) / 60))}\n          </span>\n        )}\n      </span>\n')]}
TEST_B64 = ''


def die(m):
    print("\nABORT:", m); sys.exit(1)


def mirror_of(rel):
    for src, dst in MIRRORS:
        if rel.startswith(src + "/"):
            return os.path.join(ROOT, dst + rel[len(src):])
    return None


staged = {}
for rel, parent in PREREQ.items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p):
        die(f"{rel} not found — run from the repo root with the dashboard chain applied")
    t = open(p, encoding="utf-8").read()
    if FENCE in t:
        die(f"{FENCE} already applied ({rel})")
    if parent not in t:
        die(f"prerequisite {parent} missing in {rel} — apply apply_fleet_chart_v2.py first")
for rel, ops in EDITS.items():
    t = open(os.path.join(ROOT, rel), encoding="utf-8").read()
    for kind, old, new in ops:
        n = t.count(old)
        if n != 1:
            die(f"{rel}: anchor found {n}x (need 1): {old.splitlines()[0][:80]!r}")
        t = t.replace(old, new)
    staged[rel] = t
staged[TEST] = base64.b64decode(TEST_B64).decode("utf-8")
tmp = tempfile.mkdtemp(prefix="fleet_marks_gate_")
for rel in (ROUTE, TEST):
    p = os.path.join(tmp, os.path.basename(rel))
    open(p, "w", encoding="utf-8").write(staged[rel])
    try:
        py_compile.compile(p, doraise=True)
    except py_compile.PyCompileError as e:
        die(f"py_compile failed for {rel}: {e}")
shutil.rmtree(tmp, ignore_errors=True)
st = subprocess.run(["git", "status", "--porcelain", "--"] + list(staged), cwd=ROOT, capture_output=True, text=True).stdout
dirty = [l for l in st.splitlines() if l.strip() and not l.startswith("??")]
if dirty and "--allow-dirty" not in sys.argv:
    die(f"uncommitted changes on targets ({dirty}); commit or re-run with --allow-dirty")

written = []
for rel, txt in staged.items():
    p = os.path.join(ROOT, rel)
    shutil.copy2(p, p + f".bak-{FENCE}")
    open(p, "w", encoding="utf-8").write(txt)
    written.append(rel)
    m = mirror_of(rel)
    if m and os.path.isdir(os.path.dirname(m)):
        open(m, "w", encoding="utf-8").write(txt)
open(os.path.join(ROOT, f".{FENCE}.done"), "w").write("applied\n")
print(f"   wrote {len(written)} files (backups .bak-{FENCE}; desktop trees mirrored where present)")


def rollback(reason):
    for rel in written:
        p = os.path.join(ROOT, rel)
        shutil.move(p + f".bak-{FENCE}", p)
        m = mirror_of(rel)
        if m and os.path.exists(m):
            shutil.copy2(p, m)
    os.remove(os.path.join(ROOT, f".{FENCE}.done"))
    die(reason)


if "--skip-tests" not in sys.argv:
    env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "backend"))
    for s in ("app/api/test_fleet_today_routes.py", "app/api/test_closed_recent_routes.py"):
        r = subprocess.run([sys.executable, s], cwd=os.path.join(ROOT, "backend"), env=env, capture_output=True, text=True, timeout=600)
        tail = (r.stdout.strip().splitlines() or [""])[-1]
        print(f"   {'ok  ' if r.returncode == 0 else 'FAIL'} {s} — {tail[:90]}")
        if r.returncode != 0:
            print((r.stdout + r.stderr)[-3000:])
            rollback("backend suite failed; working copy restored")
esb = os.path.join(ROOT, "frontend", "node_modules", ".bin", "esbuild")
esb = os.environ.get("ESBUILD") or (esb if os.path.exists(esb) else shutil.which("esbuild"))
if esb:
    r = subprocess.run([esb, KPIS, "--loader:.jsx=jsx", "--log-level=error", "--outfile=/dev/null"], cwd=ROOT, capture_output=True, text=True)
    if r.returncode != 0:
        rollback("esbuild parse failed; restored:\n" + r.stderr[-1500:])
    print(f"   esbuild ok {KPIS}")
print(f"── {FENCE} applied. Next: ./desktop/build-scalp.sh both  (after 15:40 IST) ──")
